using Aspire.Hosting.Testing;
using Xunit;

namespace MyApp.AppHost.Tests;

public class AppHostTests
{
    [Fact]
    public async Task AppHostStartsSuccessfully()
    {
        var builder = await DistributedApplicationTestingBuilder.CreateAsync<Projects.MyApp_AppHost>();
        await using var app = await builder.BuildAsync();
        await app.StartAsync();
        await app.WaitForResources().WaitAsync(TimeSpan.FromSeconds(30));
    }
}

using Aspire.Hosting.Testing;
using Xunit;

namespace MyApp.AppHost.Tests;

/// <summary>
/// Evaluation harness for the agentic app.
/// Add scenario-based tests here to evaluate agent behavior.
/// </summary>
public class EvaluationTests
{
    [Fact]
    public async Task AppHost_CanBuildAndStart()
    {
        var builder = await DistributedApplicationTestingBuilder.CreateAsync<Projects.MyApp_AppHost>();
        await using var app = await builder.BuildAsync();
        await app.StartAsync();

        // Verify the distributed application model is valid
        var model = app.Services.GetRequiredService<Aspire.Hosting.DistributedApplicationModel>();
        Assert.NotNull(model);
    }

    [Fact]
    public async Task AppHost_ResourcesReachRunningState()
    {
        var builder = await DistributedApplicationTestingBuilder.CreateAsync<Projects.MyApp_AppHost>();
        await using var app = await builder.BuildAsync();
        await app.StartAsync();

        // Wait for all resources to be in the running state
        await app.WaitForResources().WaitAsync(TimeSpan.FromSeconds(60));
    }
}

